lemma roundedProfile_lt_roundedRadiusBound {ρ α : ℝ}
    (hρ : 0 < ρ) (hρ_lt : ρ < 1) (hα : 0 < α) :
    roundedProfile ρ α < roundedRadiusBound ρ

lemma tendsto_roundedThresholdRatio_atTop {ρ : ℝ}
    (hρ : 0 < ρ) (hρ_lt : ρ < 1) :
    Tendsto (roundedThresholdRatio ρ) atTop atTop

lemma tendsto_roundedThresholdRatio_nhdsGT_zero {ρ : ℝ}
    (hρ : 0 < ρ) (hρ_lt : ρ < 1) :
    Tendsto (roundedThresholdRatio ρ) (𝓝[>] 0) atTop

lemma gaussianCoordinateSumDensity_pos {A q : ℝ}
    (hA : 0 < A) (hq : 0 < q) (n : ℕ) {z : ℝ}
    (hz : z ∈ Set.Ioo (0 : ℝ) ((n + 1 : ℕ) : ℝ)) :
    0 < gaussianCoordinateSumDensity A q n z

lemma gaussianOneCoordinateDensity_eq_formula (A q : ℝ) {y : ℝ}
    (hy : y ∈ Set.Ioo (0 : ℝ) 1) :
    gaussianOneCoordinateDensity A q y = gaussianOneCoordinateDensityFormula A q y

lemma gaussianTwoCoordinateDensity_pos {A q z : ℝ}
    (hA : 0 < A) (hq : 0 < q) (hz : z ∈ Set.Ioo (0 : ℝ) 2) :
    0 < gaussianTwoCoordinateDensity A q z

lemma gaussianVec_pos_of_isOpen {N : ℕ} {U : Set (Fin N → ℝ)}
    (hU : IsOpen U) (hne : U.Nonempty) :
    0 < gaussianVec N U

lemma Fmap_div_ge_of_pos_of_le {A : ℝ} {N : ℕ} {q R : ℝ}
    (g : Fin N → ℝ) (hq : 0 < q) (hqR : q ≤ R) :
    Fmap A N R g / R ≤ Fmap A N q g / q

lemma integrable_exp_mul_gaussianSquaredNorm_of_lt (N : ℕ) {t : ℝ}
    (ht : t < 1 / 2) :
    Integrable (fun g => Real.exp (t * gaussianSquaredNorm N g)) (gaussianVec N)

lemma mgf_id_gammaMeasure_of_lt {a r t : ℝ}
    (ha : 0 < a) (hr : 0 < r) (ht : t < r) :
    mgf id (gammaMeasure a r) t = (r / (r - t)) ^ a
